package provider

import (
	"context"
	"fmt"
	"os/exec"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceDNSRecord() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceDNSRecordCreate,
		ReadContext:   resourceDNSRecordRead,
		DeleteContext: resourceDNSRecordDelete,
		Schema: map[string]*schema.Schema{
			"zone": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"type": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"value": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"ttl": {
				Type:     schema.TypeInt,
				Optional: true,
				Default:  300,
				ForceNew: true,
			},
		},
	}
}

func resourceDNSRecordCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	config := meta.(*ProviderConfig)

	zone := d.Get("zone").(string)
	name := d.Get("name").(string)
	recordType := d.Get("type").(string)
	value := d.Get("value").(string)
	ttl := d.Get("ttl").(int)

	// Validate record type
	validTypes := []string{"A", "AAAA", "CNAME", "MX", "TXT", "SRV", "NS"}
	typeValid := false
	for _, t := range validTypes {
		if strings.EqualFold(recordType, t) {
			typeValid = true
			break
		}
	}
	if !typeValid {
		return diag.Errorf("invalid record type: %s", recordType)
	}

	// Use nsupdate to dynamically update DNS zone via the internal DNS API service
	// The provider communicates with dns-api-service in the dns-system namespace
	updateCmd := fmt.Sprintf(
		"server %s\nzone %s\nupdate add %s.%s %d %s %s\nsend\n",
		config.DNSServer, zone, name, zone, ttl, recordType, value,
	)

	// Shell out to nsupdate - the value field is user-controlled
	cmd := exec.CommandContext(ctx, "/bin/sh", "-c",
		fmt.Sprintf("echo '%s' | nsupdate -k %s", updateCmd, config.TSIGKeyFile))

	output, err := cmd.CombinedOutput()
	if err != nil {
		return diag.Errorf("nsupdate failed: %s\nOutput: %s", err, string(output))
	}

	d.SetId(fmt.Sprintf("%s.%s/%s", name, zone, recordType))
	return nil
}

func resourceDNSRecordRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	// Read is a no-op for this simplified provider
	return nil
}

func resourceDNSRecordDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	config := meta.(*ProviderConfig)
	zone := d.Get("zone").(string)
	name := d.Get("name").(string)
	recordType := d.Get("type").(string)

	deleteCmd := fmt.Sprintf(
		"server %s\nzone %s\nupdate delete %s.%s %s\nsend\n",
		config.DNSServer, zone, name, zone, recordType,
	)

	cmd := exec.CommandContext(ctx, "/bin/sh", "-c",
		fmt.Sprintf("echo '%s' | nsupdate -k %s", deleteCmd, config.TSIGKeyFile))

	if output, err := cmd.CombinedOutput(); err != nil {
		return diag.Errorf("nsupdate delete failed: %s\nOutput: %s", err, string(output))
	}

	d.SetId("")
	return nil
}

type ProviderConfig struct {
	DNSServer   string
	TSIGKeyFile string
}
